const e={subtitle:"A new way to fly! Climb higher, avoid obstacles, and unlock legendary skins.",download:"Download on Google Play",download_apple:"Coming soon on the App Store",f1_title:"Addictive Gameplay",f1_desc:"An infinite vertical challenge. How high can you go?",f2_title:"Pixel Art",f2_desc:"Polished retro graphics and smooth animations.",f3_title:"Competition",f3_desc:"Beat your high score and compete with players worldwide.",copyright:"© 2026 AC Games. All rights reserved.",privacy:"Privacy Policy",contact:"Contact Support",delete_account:"Account Deletion Request",home_title:"AC Games - Fun & Addictive Mobile Games",home_subtitle:"Mobile games built for the joy of play.",home_eyebrow:"Indie game studio",nav_home:"Home",nav_about:"About",nav_tech:"Technologies",nav_games:"Games",nav_contact:"Contact",hero_title:'Mobile games<br>made with <span class="accent">passion</span>',hero_passion:"passion",hero_see_games:"See our games",stat_games:"Games",stat_live:"Live on Android",stat_new:"New releases",about_title:"About",about_title_name:"AC Games",about_desc:"AC Games is an indie game studio dedicated to creating simple, addictive, and fun mobile experiences. Each project is carefully crafted to offer a unique challenge to players worldwide.",about_card1_title:"Solo developer",about_card1_desc:"Every line of code, every pixel, every design decision — made by one person.",about_card2_title:"Mobile first",about_card2_desc:"Built for Android, designed for the quick session you never want to end.",about_card3_title:"Always building",about_card3_desc:"2 games live, 1 in the pipeline. New mechanics, new challenges, always shipping.",games_title:"Games",games_header_title:"My Games",tech_title:"Technologies",tech_built_with:"Built with",game_flappy_title:"Flappy Vertical",game_flappy_desc:"The vertical twist on a classic!",game_flappy_platform:"Android",game_new_title:"Slice and Trap",game_new_desc:"A modernized take on JezzBall with boosters and a shop.",game_new_platform:"Coming 2026",game_block_drift_title:"Block Drift",game_block_drift_desc:"A gravity-based block puzzle challenge.",game_block_drift_platform:"Android",coming_soon:"Coming Soon",live_badge:"Live",contact_title:"Get in touch",contact_desc:"Got a bug to report, a question about one of the games, or just want to say hi? I'm a solo dev — I read every message.",contact_game_support:"Game Support",contact_game_support_desc:"Issues with Flappy Vertical or Block Drift? Describe the problem and your device.",contact_deletion_desc:"Use the deletion form for faster processing.",contact_response_time:"Response time",contact_response_time_desc:"Usually within 24–48 hours on weekdays.",contact_name:"Name",contact_email:"Email",contact_message:"Message",contact_send:"Send Message",s1_title:"Strategic Puzzles",s1_desc:"Trap the bouncing balls by slicing the arena. Plan your cuts carefully!",s2_title:"Boosters",s2_desc:"Use special power-ups to freeze time, extend your lines, and more.",s3_title:"In-Game Shop",s3_desc:"Unlock custom ball skins, new slice animations, and colorful arenas.",features_title:"Features",bd_subtitle:"Master the gravity, slide the blocks, and solve the ultimate puzzle challenge.",bd_features_title:"Why you'll love it",bd1_title:"Gravity Mechanics",bd1_desc:"Experience a unique twist on block puzzles where gravity changes everything.",bd2_title:"100+ Levels",bd2_desc:"Challenge yourself with over 100 hand-crafted gravity puzzles in Adventure mode.",bd3_title:"Endless Mode",bd3_desc:"Test your survival skills in an infinite challenge. How long can you last?",stat_levels:"Levels",stat_endless:"Endless mode",stat_free:"Free",stat_to_play:"to play",privacy_title:"Privacy Policy",privacy_eyebrow:"Legal",privacy_meta:"Last updated: 4th January 2026",privacy_highlight:"Your privacy matters. Our games are designed to be fun, and we aim to be transparent about the data processed when you play them.",privacy_intro:'Thank you for playing our games. This Privacy Policy explains how we handle information when you use our mobile applications (the "Games").',toc_title:"On this page",toc_1:"1. Information We Collect",toc_2:"2. How We Use Your Information",toc_3:"3. Data Sharing",toc_4:"4. Data Security",toc_5:"5. Children's Privacy",toc_6:"6. Your Rights",toc_7:"7. Changes to This Policy",toc_8:"8. Contact Us",privacy_s1_title:"1. Information We Collect and Why",privacy_s1_p1:"To provide and improve our Games, we use third-party services that may collect information.",privacy_firebase:"Firebase (Google)",privacy_firebase_p1:"We use Firebase for essential game functionalities:",privacy_firebase_li1:"<strong>Firebase Authentication</strong> — to allow you to create an account (via Google Sign-In or email/password) and save your progress securely. This handles your email address, a user ID, and authentication tokens.",privacy_firebase_li2:"<strong>Cloud Firestore</strong> — to store your game data such as high scores, credits, unlocked items, and friends lists, linked to your user ID.",privacy_firebase_li3:"<strong>Firebase Crashlytics</strong> — to detect and analyze crashes. This collects crash-related information including device state, type, and OS to help us fix bugs. It does not collect personally identifiable information.",privacy_admob:"Google AdMob",privacy_admob_p1:"We use Google AdMob to show advertisements. AdMob may collect and use data to provide personalized ads, including:",privacy_admob_li1:"Device identifiers (like the Advertising ID).",privacy_admob_li2:"Location data (if location services are enabled).",privacy_admob_li3:"Information about your interactions with ads.",privacy_admob_optout:`You can manage your ad preferences in your device's settings — "Limit Ad Tracking" on iOS or "Opt out of Ads Personalization" on Android.`,privacy_s2_title:"2. How We Use Your Information",privacy_s2_li1:"To operate and maintain the Games (e.g., saving your scores).",privacy_s2_li2:"To fix bugs and improve the user experience (via Crashlytics).",privacy_s2_li3:"To support the Games financially through advertising (via AdMob).",privacy_s2_li4:"To provide social features like leaderboards and friend lists.",privacy_s3_title:"3. Data Sharing",privacy_s3_p1:"We do not manually share your personal data with any third parties, except for the data automatically collected by the services mentioned above (Firebase and AdMob) as part of their standard operation.",privacy_s4_title:"4. Data Security",privacy_s4_p1:"We take reasonable measures to protect your information. Data stored on Firebase is secured by Google's infrastructure. However, no method of transmission over the internet or electronic storage is 100% secure.",privacy_s5_title:"5. Children's Privacy",privacy_s5_p1:"Our Games are not intended for children under the age of 13. We do not knowingly collect personal information from children under 13. If you believe we have inadvertently collected such information, please contact us so we can promptly remove it.",privacy_s6_title:"6. Your Rights",privacy_s6_p1:'Depending on your location (e.g., if you are in the European Union), you may have rights regarding your personal data, such as the right to access, correct, or delete your data. Our Games provide an in-app feature to delete your account. You can also use the <a href="https://docs.google.com/forms/d/e/1FAIpQLSdZzHMHshPBBY7BNYXii3B9XnnJP37MFufVLUTgq1Bfntp4zA/viewform?usp=preview" target="_blank">account deletion request form</a>.',privacy_s7_title:"7. Changes to This Privacy Policy",privacy_s7_p1:"We may update this Privacy Policy from time to time. We will notify you of any changes by posting the new Privacy Policy in the Game or on our website. You are advised to review this policy periodically.",privacy_s8_title:"8. Contact Us",privacy_s8_p1:'If you have any questions about this Privacy Policy, please contact us via the in-game support feature or through our <a href="/contact/">contact page</a>.',form_success:"Message sent successfully! We'll get back to you soon.",form_send_error:"Failed to send message. Please try again later or contact us directly.",form_error:"Please fill out all required fields.",cookie_text:"We use cookies to ensure you get the best experience on our website.",cookie_accept:"Got it!",captcha_error:"Please complete the security check.","404_title":"Page Not Found","404_message":"Sorry, the page you are looking for could not be found.","404_button":"Go to Homepage",waitlist_placeholder:"your@email.com",waitlist_button:"Notify me at launch",waitlist_label:"No spam. One email when it drops.",waitlist_success:"Thanks! We'll notify you."};export{e as translations_en};
